sealed class Outcome192 {
    data class Success(val payload: String) : Outcome192()
    data object Failure : Outcome192()
}

fun describe192(outcome: Outcome192): String = when (outcome) {
    is Outcome192.Success -> outcome.payload
    Outcome192.Failure -> "failed"
}
